use std::collections::BTreeMap;
use std::fs;
use std::path::Path;

use crate::codegen::{Case, Clause, ContractSchema, Operation};

/// Parse a Markdown contract (generated by `caac md`) into a JSON schema.
#[allow(clippy::collapsible_if, clippy::collapsible_match)]
pub fn parse_markdown(content: &str) -> ContractSchema {
    let mut name = String::from("Contract");
    let mut version = String::from("0.1.0");
    let mut description = String::new();
    let mut terms: BTreeMap<String, String> = BTreeMap::new();
    let mut operations: Vec<Operation> = Vec::new();
    let mut clauses: Vec<Clause> = Vec::new();
    let mut cases: Vec<Case> = Vec::new();
    let mut exclusions: Vec<String> = Vec::new();

    let lines: Vec<&str> = content.lines().collect();
    let mut i = 0;
    let mut current_section = String::new();
    let mut current_op: Option<String> = None;

    while i < lines.len() {
        let line = lines[i].trim();

        // Title
        if line.starts_with("# ") && name == "Contract" {
            name = line.trim_start_matches("# ").to_owned();
            i += 1;
            continue;
        }

        // Revision line
        if line.starts_with("Revision:") {
            if let Some(v) = line.split_whitespace().nth(1) {
                version = v.trim_end_matches('.').to_owned();
            }
            i += 1;
            continue;
        }

        // Section headers
        if line.starts_with("## ") {
            current_section = line.trim_start_matches("## ").to_owned();
            current_op = None;
            i += 1;
            continue;
        }
        if line.starts_with("### ") {
            current_op = Some(line.trim_start_matches("### ").to_owned());
            i += 1;
            continue;
        }

        match current_section.as_str() {
            "Terms and inputs" => {
                // Format: An `Term` is definition..
                if line.starts_with("An `") {
                    if let Some(end) = line.find('`') {
                        // find closing backtick
                        if let Some(end2) = line[end + 1..].find('`') {
                            let term = line[end + 1..end + 1 + end2].to_owned();
                            let rest = line[end + 1 + end2 + 1..].trim();
                            let def = rest
                                .trim_start_matches("is ")
                                .trim()
                                .trim_end_matches("..")
                                .trim()
                                .to_owned();
                            terms.insert(term, def);
                        }
                    }
                }
            }
            "Operation signatures" => {
                // Format: - `name(params)` -> `returns`
                if line.starts_with("- `") {
                    if let Some(op) = parse_op_sig(line) {
                        operations.push(op);
                    }
                }
            }
            "Clauses" => {
                // Format: ID | actor obligation  or  ID | actor ID obligation
                if line.contains(" | ") {
                    if let Some(clause) = parse_clause_line(line) {
                        // Assign to current operation if matching
                        if let Some(ref op_name) = current_op {
                            if let Some(op) = operations.iter_mut().find(|o| o.name == *op_name) {
                                op.clauses.push(clause.id.clone());
                            }
                        }
                        clauses.push(clause);
                    }
                }
            }
            "Contract cases" => {
                // Table row: | name | input | expected | clauses |
                if line.starts_with("|")
                    && !line.starts_with("| ---")
                    && !line.starts_with("| Case |")
                {
                    let parts: Vec<&str> = line.split('|').map(|s| s.trim()).collect();
                    if parts.len() >= 5 {
                        let name = parts[1].to_owned();
                        let input = parts[2].to_owned();
                        let expected = parts[3].to_owned();
                        let clause_str = parts[4].to_owned();
                        let clause_list: Vec<String> = clause_str
                            .split(',')
                            .map(|s| s.trim().to_owned())
                            .filter(|s| !s.is_empty())
                            .collect();
                        cases.push(Case {
                            name,
                            input,
                            expected,
                            clauses: clause_list,
                        });
                    }
                }
            }
            "Exclusions" => {
                if line.starts_with("- ") {
                    exclusions.push(line.trim_start_matches("- ").to_owned());
                }
            }
            _ => {}
        }

        // Description: first non-empty line after title before terms
        if current_section.is_empty()
            && !line.is_empty()
            && !line.starts_with("#")
            && !line.starts_with("---")
            && description.is_empty()
            && !line.starts_with("Revision:")
        {
            // skip frontmatter
            if !line.starts_with("title:")
                && !line.starts_with("doc_type:")
                && !line.starts_with("audience:")
                && !line.starts_with("status:")
                && !line.starts_with("publication:")
            {
                // only capture after frontmatter ends
            }
        }

        i += 1;
    }

    // Capture description from the line after revision
    // (simple: first paragraph after title that isn't a section)
    let mut in_frontmatter = false;
    let mut fm_done = false;
    for line in &lines {
        let t = line.trim();
        if t == "---" {
            if !in_frontmatter {
                in_frontmatter = true;
            } else {
                fm_done = true;
            }
            continue;
        }
        if in_frontmatter && !fm_done {
            continue;
        }
        if fm_done
            && !t.is_empty()
            && !t.starts_with("#")
            && !t.starts_with("Revision:")
            && description.is_empty()
        {
            description = t.to_owned();
            break;
        }
    }

    ContractSchema {
        name,
        version,
        description,
        terms,
        operations,
        clauses,
        cases,
        exclusions,
        extends: Vec::new(),
    }
}

fn parse_op_sig(line: &str) -> Option<Operation> {
    let line = line.trim().trim_start_matches("- ").trim();
    let backtick_start = line.find('`')?;
    let backtick_end = line[backtick_start + 1..].find('`')? + backtick_start + 1;
    let sig = &line[backtick_start + 1..backtick_end];
    let rest = line[backtick_end + 1..].trim();

    let paren_open = sig.find('(')?;
    let paren_close = sig.rfind(')')?;
    let name = sig[..paren_open].trim().to_owned();
    let params = sig[paren_open + 1..paren_close].trim().to_owned();

    let returns = if rest.starts_with("->") {
        rest.trim_start_matches("->")
            .trim()
            .trim_matches('`')
            .trim()
            .to_owned()
    } else {
        "()".to_owned()
    };

    Some(Operation {
        name,
        params,
        returns,
        clauses: Vec::new(),
    })
}

fn parse_clause_line(line: &str) -> Option<Clause> {
    let (left, right) = line.split_once('|')?;
    let id = left.trim().to_owned();
    if !valid_id(&id) {
        return None;
    }
    let sentence = right.trim().to_owned();
    // Split into actor + obligation: "Actor must ..."
    let mut parts = sentence.splitn(2, ' ');
    let actor = parts.next()?.to_owned();
    let obligation = parts.next().unwrap_or("").to_owned();
    Some(Clause {
        id,
        actor,
        obligation,
    })
}

fn valid_id(identifier: &str) -> bool {
    let mut parts = identifier.split('-').collect::<Vec<_>>();
    if parts.len() < 2 {
        return false;
    }
    let sequence = parts.pop().unwrap();
    if sequence.len() != 3 || !sequence.bytes().all(|b| b.is_ascii_digit()) {
        return false;
    }
    parts.iter().all(|part| {
        let mut bytes = part.bytes();
        matches!(bytes.next(), Some(b'A'..=b'Z'))
            && bytes.all(|b| b.is_ascii_uppercase() || b.is_ascii_digit())
    })
}

pub fn run_parse(input: &Path, output: &Path) -> i32 {
    let content = match fs::read_to_string(input) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("ERROR: cannot read {}: {}", input.display(), e);
            return 2;
        }
    };

    let schema = parse_markdown(&content);
    let json = match serde_json::to_string_pretty(&schema) {
        Ok(j) => j,
        Err(e) => {
            eprintln!("ERROR: cannot serialize: {}", e);
            return 2;
        }
    };

    if let Some(parent) = output.parent() {
        let _ = fs::create_dir_all(parent);
    }
    match fs::write(output, json) {
        Ok(_) => {
            println!("Parsed: {}", output.display());
            println!(
                "Operations: {}, Clauses: {}, Cases: {}",
                schema.operations.len(),
                schema.clauses.len(),
                schema.cases.len()
            );
            0
        }
        Err(e) => {
            eprintln!("ERROR: cannot write {}: {}", output.display(), e);
            2
        }
    }
}
